css:
.makebend-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1c2530;
    background: linear-gradient(168deg, #eceff2 0%, #e3e8ec 55%, #dce3e6 100%);
    border-radius: 16px;
}

.makebend-container * {
    box-sizing: border-box;
}

.makebend-header {
    position: relative;
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #1f2a37 0%, #2c3e50 50%, #34556e 100%);
    color: #f1f5f8;
    border-radius: 14px;
    margin-bottom: 18px;
    border-bottom: 5px solid #e8973a;
    box-shadow: 0 14px 32px rgba(31, 42, 55, 0.32);
}

.makebend-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.4px;
    color: #ffffff;
}

.makebend-header-tag {
    display: inline-block;
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #ffcf99;
    background: rgba(232, 151, 58, 0.14);
    border: 1px solid rgba(232, 151, 58, 0.42);
    padding: 5px 14px;
    border-radius: 6px;
}

.makebend-subtitle {
    margin: 0 auto;
    max-width: 830px;
    font-size: 1rem;
    line-height: 1.55;
    color: #cdd9e2;
}

.makebend-firm {
    display: flex;
    gap: 12px;
    margin-bottom: 18px;
}

.makebend-firm-block {
    flex: 1;
    background: #ffffff;
    border-radius: 10px;
    padding: 14px 18px;
    box-shadow: 0 4px 12px rgba(31, 42, 55, 0.08);
    display: flex;
    flex-direction: column;
    gap: 4px;
    border-left: 5px solid #34556e;
}

.makebend-firm-anchor {
    border-left-color: #e8973a;
}

.makebend-firm-name {
    font-weight: 800;
    font-size: 1.02rem;
    color: #2c3e50;
}

.makebend-firm-anchor .makebend-firm-name {
    color: #c2701b;
}

.makebend-firm-meta {
    font-size: 0.82rem;
    color: #5d6b78;
    line-height: 1.4;
}

.makebend-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #455463;
    margin-bottom: 16px;
    padding: 2px 4px;
}

.makebend-period-counter #currentDay,
.makebend-period-counter #maxPeriods {
    font-weight: 800;
    color: #c2701b;
}

.makebend-round-name {
    background: rgba(52, 85, 110, 0.12);
    color: #2c4356;
    padding: 3px 12px;
    border-radius: 6px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.makebend-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b06414;
    background: rgba(232, 151, 58, 0.14);
    border: 1px solid rgba(232, 151, 58, 0.32);
    padding: 4px 12px;
    border-radius: 6px;
}

.makebend-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.makebend-status-card {
    background: #ffffff;
    border-radius: 10px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 14px rgba(31, 42, 55, 0.08);
    border-top: 4px solid #34556e;
}

.makebend-card-savings { border-top-color: #2f8f6b; }
.makebend-card-margin { border-top-color: #34556e; }
.makebend-card-covenant { border-top-color: #c2701b; }
.makebend-card-capability { border-top-color: #6a55b0; }

.makebend-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b7785;
}

.makebend-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2c3e50;
    font-variant-numeric: tabular-nums;
}

.makebend-card-savings .makebend-value { color: #2f8f6b; }
.makebend-card-margin .makebend-value { color: #34556e; }
.makebend-card-covenant .makebend-value { color: #c2701b; }
.makebend-card-capability .makebend-value { color: #6a55b0; }

.makebend-sublabel {
    font-size: 0.75rem;
    color: #79858f;
    line-height: 1.35;
}

.makebend-card-covenant.makebend-covenant-breach { border-top-color: #cf3f3f; }
.makebend-card-covenant.makebend-covenant-breach .makebend-value { color: #cf3f3f; }
.makebend-card-covenant.makebend-covenant-safe { border-top-color: #2f8f6b; }
.makebend-card-covenant.makebend-covenant-safe .makebend-value { color: #2f8f6b; }

.makebend-card-margin.makebend-margin-danger .makebend-value { color: #cf3f3f; }
.makebend-card-margin.makebend-margin-danger { border-top-color: #cf3f3f; }

.makebend-card-savings.makebend-savings-hit { border-top-color: #2f8f6b; }
.makebend-card-savings.makebend-savings-short .makebend-value { color: #c2701b; }
.makebend-card-savings.makebend-savings-short { border-top-color: #c2701b; }

.makebend-risk-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #d8dfe4;
    color: #455463;
    padding: 10px 18px;
    border-radius: 8px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.makebend-risk-bar #riskDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #cf3f3f;
    font-weight: 800;
}

.makebend-risk-bar.makebend-risk-low #riskDisplay { color: #2f8f6b; }
.makebend-risk-bar.makebend-risk-mid #riskDisplay { color: #c2701b; }

.makebend-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #e8973a;
    border-radius: 10px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 14px rgba(31, 42, 55, 0.07);
}

.makebend-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.makebend-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #2c3e50;
    margin-bottom: 6px;
}

.makebend-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a4956;
}

.makebend-briefing-text strong { color: #2c4356; }
.makebend-briefing-text em { color: #c2701b; font-style: italic; }

.makebend-controls {
    background: #ffffff;
    border-radius: 12px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 14px rgba(31, 42, 55, 0.07);
}

.makebend-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #2c3e50;
    border-bottom: 2px solid #e6eaed;
    padding-bottom: 8px;
}

.makebend-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2a3845;
    margin: 14px 0 6px;
}

.makebend-budget-banner {
    background: linear-gradient(135deg, #fbf0e2 0%, #f7e6d2 100%);
    border: 1px solid #e8c79d;
    border-left: 5px solid #e8973a;
    border-radius: 8px;
    padding: 12px 14px;
    font-size: 0.88rem;
    font-weight: 600;
    color: #8a4f12;
    line-height: 1.45;
    margin-bottom: 4px;
}

.makebend-container select,
.makebend-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c4ced5;
    border-radius: 7px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #1c2530;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.makebend-container select:focus,
.makebend-container input[type="number"]:focus {
    outline: none;
    border-color: #e8973a;
    box-shadow: 0 0 0 3px rgba(232, 151, 58, 0.18);
}

.makebend-container select option {
    background-color: #ffffff;
    color: #1c2530;
}

.makebend-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #e8973a;
}

.makebend-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #455463;
    margin-top: 4px;
}

.makebend-range-readout span:nth-child(2) {
    color: #c2701b;
    font-weight: 800;
}

.makebend-hint {
    font-size: 0.8rem;
    color: #79858f;
    margin-top: 6px;
    line-height: 1.4;
    font-style: italic;
}

.makebend-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.makebend-container .btn-primary {
    background: linear-gradient(135deg, #2c3e50 0%, #34556e 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 7px;
    box-shadow: 0 8px 16px rgba(44, 62, 80, 0.30);
}

.makebend-container .btn-primary:hover {
    filter: brightness(1.12);
}

.makebend-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c4ced5;
    color: #5d6b78;
    background: transparent;
}

.makebend-coach {
    background: linear-gradient(160deg, #1f2a37 0%, #2c3e50 100%);
    color: #dde7ee;
    border-radius: 12px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border-left: 5px solid #e8973a;
    box-shadow: 0 8px 18px rgba(31, 42, 55, 0.24);
}

.makebend-coach-header {
    font-size: 0.77rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ffcf99;
    margin-bottom: 8px;
}

.makebend-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.makebend-coach-body strong { color: #6fd0a8; }
.makebend-coach-body em { color: #ffcf99; font-style: italic; }

.makebend-history,
.makebend-chart {
    background: #ffffff;
    border-radius: 12px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 14px rgba(31, 42, 55, 0.07);
}

.makebend-history h3,
.makebend-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #2c3e50;
}

.makebend-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a4956;
}

.makebend-container table#usfHistoryTable th {
    background: #eef1f4;
    color: #34556e;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.71rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d6dde2;
}

.makebend-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef1f3;
    color: #3a4956;
}

.makebend-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f6f8f9;
}

.makebend-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .makebend-container {
        padding: 14px;
    }
    .makebend-header h1 {
        font-size: 1.7rem;
    }
    .makebend-firm {
        flex-direction: column;
    }
    .makebend-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .makebend-value {
        font-size: 2rem;
    }
    .makebend-clock {
        margin-left: 0;
    }
    .makebend-period-counter {
        font-size: 0.88rem;
    }
    .makebend-risk-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .makebend-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion debrief (append-only, makebend-cm-*) ===== */
.makebend-cm { color: #24303a; font-family: inherit; }
.makebend-cm-generic { font-size: 15px; text-align: center; }
.makebend-cm-scoreband { text-align: center; padding: 6px 0 14px; border-bottom: 1px solid rgba(31,42,55,0.12); margin-bottom: 16px; }
.makebend-cm-score { font-size: 46px; font-weight: 700; line-height: 1; color: #2f8f6b; }
.makebend-cm-score-max { font-size: 20px; font-weight: 500; color: #79858f; margin-left: 2px; }
.makebend-cm-tier { font-size: 20px; font-weight: 600; margin-top: 6px; color: #24303a; }
.makebend-cm-caption { font-size: 11.5px; letter-spacing: .05em; text-transform: uppercase; color: #79858f; margin-top: 4px; }
.makebend-cm-kpis { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin-bottom: 14px; }
.makebend-cm-kpi { flex: 1 1 92px; min-width: 92px; background: rgba(47,143,107,0.07); border: 1px solid rgba(47,143,107,0.18); border-radius: 10px; padding: 10px 8px; text-align: center; }
.makebend-cm-kpi-val { display: block; font-size: 21px; font-weight: 700; color: #24303a; }
.makebend-cm-kpi-lbl { display: block; font-size: 11px; margin-top: 3px; color: #55636e; }
.makebend-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; margin-bottom: 14px; }
.makebend-cm-chip { font-size: 12.5px; font-weight: 600; padding: 5px 11px; border-radius: 999px; border: 1px solid transparent; }
.makebend-cm-chip.is-met { background: rgba(47,143,107,0.14); border-color: rgba(47,143,107,0.42); color: #1f6e50; }
.makebend-cm-chip.is-missed { background: rgba(197,74,74,0.12); border-color: rgba(197,74,74,0.4); color: #a23b3b; }
.makebend-cm-insights { margin: 0; padding-left: 18px; }
.makebend-cm-insights li { font-size: 13.5px; line-height: 1.5; color: #3a4753; margin-bottom: 7px; }

