(function() {
    'use strict';

    class MakeBuyBendAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Make, Buy, or Bend`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Andicorp Manufactura S.A.C.), in S/ millions.
            this.REVENUE = 520;            // S/ 520M annual revenue
            this.START_MARGIN = 12;        // EBITDA margin % (S/ 62.4M)
            this.NOACTION_MARGIN = 7.5;    // projected margin if nothing changes
            this.TARGET = 47;              // S/ 47M cost-reduction mandate (15%)
            this.START_COVENANT = 2.9;     // Net Debt/EBITDA at start
            this.COVENANT_CAP = 3.0;       // breaches above this
            this.ANCHOR = 166;             // S/ 166M anchor-client revenue (32%)
            this.TOOLING_SAVE = 4.5;       // S/ 4.5M gross tooling-outsourcing saving
            this.LINE_DOWN_DAY = 0.18;     // S/ 180,000/day in S/ M
            this.FORCE_MAJEURE_DAYS = 42;  // 6-week force-majeure delay
            this.RESILIENCE_BUDGET = 6;    // S/ 6M constrained resilience budget (R3)

            // Concept truths (the modelled best path).
            this.TRUE_TOOLING_CLASS = `core`;
            this.TRUE_MOTOR_CLASS = `fragile`;
            this.TRUE_CONTEXT_CLASS = `commodity`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    savings: 0,                       // S/ M of annualised cost taken out
                    margin: this.START_MARGIN,        // EBITDA margin %
                    covenant: this.START_COVENANT,    // Net Debt/EBITDA
                    capability: 70,                   // capability + resilience index (0-100)
                    renewalRisk: 78,                  // anchor-renewal risk index 0-100 (lower safer)
                    resilienceSpent: 0,               // S/ M committed to resilience (R3)
                    // ---- sticky run-defining flags (set when an error is committed) ----
                    coreLost: false,                  // outsourced/cut the tooling core -> caps everything
                    flatHaircut: false,               // across-the-board cut
                    identityInertia: false,           // kept everything in-house, no leverage move
                    overInsured: false,               // dual-sourced/buffered everything
                    lineDown: false,                  // single-source line-down materialised
                    lineDownCost: 0,                  // S/ M lost to the force-majeure idle
                    misdiagnosed: false,              // failed to separate feels-core from is-core
                    savingsHistory: [0],
                    marginHistory: [this.START_MARGIN],
                    covenantHistory: [this.START_COVENANT],
                    capabilityHistory: [70],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the classic errors — a blind
                // click-through must NOT auto-win.
                state.decisions = {
                    toolingClass: `commodity`,
                    motorClass: `commodity`,
                    contextClass: `core`,
                    diag: 40,
                    approach: `flat`,
                    toolingDecision: `buy`,
                    contextDecision: `make`,
                    anchor: `price`,
                    dualSource: `no`,
                    safetyStock: 0,
                    nearshore: 0,
                    breadth: 0,
                    pitch: `cost`,
                    model: `fixed`,
                    kpi: `savings`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);
            const val = (id) => { const el = document.getElementById(id); return el ? el.value : null; };

            if (round === 1) {
                const tc = val(`toolingClassInput`); if (tc !== null) decisions.toolingClass = tc;
                const mc = val(`motorClassInput`); if (mc !== null) decisions.motorClass = mc;
                const cc = val(`contextClassInput`); if (cc !== null) decisions.contextClass = cc;
                const dg = val(`diagInput`); if (dg !== null) decisions.diag = parseInt(dg, 10);
                if (!Number.isFinite(decisions.diag) || decisions.diag < 0 || decisions.diag > 100) {
                    warn(`warn_diag_range`); return false;
                }
            } else if (round === 2) {
                const ap = val(`approachInput`); if (ap !== null) decisions.approach = ap;
                const td = val(`toolingDecisionInput`); if (td !== null) decisions.toolingDecision = td;
                const cd = val(`contextDecisionInput`); if (cd !== null) decisions.contextDecision = cd;
                const an = val(`anchorInput`); if (an !== null) decisions.anchor = an;
                if (!decisions.approach || !decisions.toolingDecision) { warn(`warn_choose`); return false; }
            } else if (round === 3) {
                const dsv = val(`dualSourceInput`); if (dsv !== null) decisions.dualSource = dsv;
                const ss = val(`safetyStockInput`); if (ss !== null) decisions.safetyStock = parseFloat(ss);
                const ns = val(`nearshoreInput`); if (ns !== null) decisions.nearshore = parseFloat(ns);
                const br = val(`breadthInput`); if (br !== null) decisions.breadth = parseFloat(br);
                if (!Number.isFinite(decisions.safetyStock) || !Number.isFinite(decisions.nearshore) || !Number.isFinite(decisions.breadth)) {
                    warn(`warn_budget`); return false;
                }
                const dualCost = decisions.dualSource === `yes` ? 2.5 : 0;
                const spend = dualCost + decisions.safetyStock + decisions.nearshore + decisions.breadth;
                if (spend > this.RESILIENCE_BUDGET + 0.001) {
                    warn(`warn_overbudget`); return false;
                }
            } else if (round === 4) {
                const pi = val(`pitchInput`); if (pi !== null) decisions.pitch = pi;
                const md = val(`modelInput`); if (md !== null) decisions.model = md;
                const kp = val(`kpiInput`); if (kp !== null) decisions.kpi = kp;
                const cv = val(`convictionInput`); if (cv !== null) decisions.conviction = parseInt(cv, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let savingsDelta = 0, marginDelta = 0, covenantDelta = 0, capDelta = 0, riskDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // ---- Map the Capability: separate what feels core from what is core. ----
                const toolingRight = d.toolingClass === this.TRUE_TOOLING_CLASS;
                const motorRight = d.motorClass === this.TRUE_MOTOR_CLASS;
                const contextRight = d.contextClass === this.TRUE_CONTEXT_CLASS;
                const correct = (toolingRight ? 1 : 0) + (motorRight ? 1 : 0) + (contextRight ? 1 : 0);

                // Tooling = the core capability the diagnosis hinges on.
                if (toolingRight) { capDelta += 4; riskDelta -= 5; }
                else if (d.toolingClass === `commodity`) { capDelta -= 3; riskDelta += 6; coachKey = `coach_r1_toolcommodity`; }
                else { capDelta += 1; }

                // Motors = the single-point-of-failure resilience risk.
                if (motorRight) { capDelta += 3; riskDelta -= 2; }
                else if (d.motorClass === `commodity`) { capDelta -= 3; riskDelta += 4; if (coachKey === `coach_default`) coachKey = `coach_r1_motorcommodity`; }

                // Fleet/IT/CS = context, the natural candidates to variabilise.
                if (contextRight) { capDelta += 2; }
                else if (d.contextClass === `core`) { capDelta -= 1; if (coachKey === `coach_default`) coachKey = `coach_r1_contextcore`; }

                // Diagnostic rigour.
                if (d.diag >= 60) { capDelta += 2; riskDelta -= 3; }
                else if (d.diag <= 25) { riskDelta += 3; }

                if (correct <= 1) { ds.misdiagnosed = true; }

                if (correct === 3) { coachKey = `coach_r1_sharp`; summaryKey = `sum_r1_good`; }
                else if (correct === 0) { summaryKey = `sum_r1_bad`; if (coachKey === `coach_default`) coachKey = `coach_r1_blind`; }
                else { summaryKey = `sum_r1_weak`; }
            } else if (round === 2) {
                // ---- Make, Buy, or Bend under the S/ 47M target. ----

                // (1) Overall approach (Common Errors 2 & 5; decision tree #2 & #4).
                switch (d.approach) {
                    case `protect`:
                        // Selective, capability-weighted — the modelled approach.
                        savingsDelta += 26; marginDelta += 1.4; covenantDelta -= 0.15; capDelta += 3; riskDelta -= 6;
                        break;
                    case `flat`:
                        // Across-the-board haircut — shrinks the differentiator at overhead's rate.
                        ds.flatHaircut = true;
                        savingsDelta += 24; marginDelta += 1.0; covenantDelta -= 0.10; capDelta -= 7; riskDelta += 8;
                        coachKey = `coach_r2_flat`;
                        break;
                    case `trim`:
                        // Identity-driven inertia — finds only ~S/ 18M, no operating leverage.
                        ds.identityInertia = true;
                        savingsDelta += 11; marginDelta += 0.4; covenantDelta += 0.05; capDelta += 1; riskDelta += 2;
                        coachKey = `coach_r2_trim`;
                        break;
                }

                // (2) Tooling: Make, Buy, or Bend (Common Error 1; decision tree #1 — the HEADLINE anti-pattern).
                switch (d.toolingDecision) {
                    case `buy`:
                        // Outsourcing the core for a small saving -> STICKY core-lost flag.
                        ds.coreLost = true;
                        savingsDelta += this.TOOLING_SAVE; marginDelta += 0.3;
                        capDelta -= 22; riskDelta += 28;
                        coachKey = `coach_r2_toolbuy`;
                        break;
                    case `make`:
                        // Keep 100% in-house, change nothing — no saving, fixed cost stays.
                        capDelta += 2; riskDelta -= 1;
                        if (coachKey === `coach_default`) coachKey = `coach_r2_toolmake`;
                        break;
                    case `bend`:
                        // Nearshore co-dev overflow + retain the design-iteration core and SLA.
                        savingsDelta += 6; marginDelta += 0.5; covenantDelta -= 0.05;
                        capDelta += 6; riskDelta -= 8;
                        if (coachKey === `coach_default`) coachKey = `coach_r2_toolbend`;
                        break;
                }

                // (3) Context block: variabilising is the operating-leverage move (key concept 5).
                switch (d.contextDecision) {
                    case `buy`:
                        savingsDelta += 22; marginDelta += 0.9; covenantDelta -= 0.20; capDelta += 1;
                        break;
                    case `bend`:
                        savingsDelta += 11; marginDelta += 0.4; covenantDelta -= 0.08;
                        break;
                    case `make`:
                        // Keeps fixed cost; misses the leverage the covenant needs.
                        ds.identityInertia = true;
                        savingsDelta += 1; covenantDelta += 0.05;
                        break;
                }

                // (4) Anchor guarantee (decision tree #1).
                switch (d.anchor) {
                    case `sla`:
                        riskDelta -= 16; capDelta += 3;
                        if (d.toolingDecision === `bend` && d.approach === `protect`) coachKey = `coach_r2_strong`;
                        break;
                    case `price`:
                        // A pure price fight against an 8% underbid erodes margin and isn't what the clause asks.
                        marginDelta -= 0.8; riskDelta += 4;
                        if (coachKey === `coach_default`) coachKey = `coach_r2_price`;
                        break;
                    case `none`:
                        riskDelta += 10;
                        if (coachKey === `coach_default`) coachKey = `coach_r2_anchornone`;
                        break;
                }

                // If the tooling core was already let go, an SLA you can't back rings hollow.
                if (ds.coreLost && d.anchor === `sla`) { riskDelta += 12; capDelta -= 2; coachKey = `coach_r2_hollow`; }

                summaryKey = (d.approach === `protect` && d.toolingDecision === `bend` && d.contextDecision !== `make` && d.anchor === `sla`) ? `sum_r2_good` :
                             (ds.coreLost ? `sum_r2_corelost` :
                             (d.approach === `flat` ? `sum_r2_flat` :
                             (ds.identityInertia ? `sum_r2_inertia` : `sum_r2_weak`)));
            } else if (round === 3) {
                // ---- Invest in resilience under a shrinking budget (force majeure hits). ----
                const dualCost = d.dualSource === `yes` ? 2.5 : 0;
                const spend = dualCost + d.safetyStock + d.nearshore + d.breadth;
                ds.resilienceSpent = Math.round((ds.resilienceSpent + spend) * 100) / 100;

                // Every Sol on resilience is a Sol not on the cost cut: spend reduces booked savings.
                savingsDelta -= spend;

                // (a) Dual-source the two true single-points-of-failure (the right-tiered move).
                if (d.dualSource === `yes`) { riskDelta -= 8; capDelta += 4; }

                // (b) Safety stock vs the 6-week (42-day) idle at S/ 180k/day.
                // Protection = whether Line 2 keeps running through the force majeure.
                let protectedDays = 0;
                if (d.safetyStock >= 2) protectedDays = 42;
                else if (d.safetyStock >= 1.5) protectedDays = 21;
                const exposedDays = Math.max(0, this.FORCE_MAJEURE_DAYS - protectedDays);
                // Dual-source halves the residual exposure (a qualified second source ramps).
                const exposureFactor = (d.dualSource === `yes`) ? 0.4 : 1.0;
                const lineDownCost = Math.round(exposedDays * this.LINE_DOWN_DAY * exposureFactor * 100) / 100;

                if (lineDownCost > 0.01) {
                    ds.lineDown = true;
                    ds.lineDownCost = Math.round((ds.lineDownCost + lineDownCost) * 100) / 100;
                    // The idle destroys contribution -> hits savings, margin and the covenant.
                    savingsDelta -= lineDownCost;
                    marginDelta -= lineDownCost / this.REVENUE * 100;
                    covenantDelta += 0.18;
                    riskDelta += 8;
                }
                if (d.safetyStock >= 2 || d.dualSource === `yes`) { capDelta += 3; }
                if (d.safetyStock <= 0 && d.dualSource === `no`) { coachKey = `coach_r3_zero`; }

                // (c) Nearshore tooling partner underwrites the SLA.
                if (d.nearshore >= 1.5) { riskDelta -= 7; capDelta += 5; }

                // (d) Blanket dual-source/buffer everything = over-insuring (Common Error 4; decision tree #5).
                if (d.breadth >= 4) {
                    ds.overInsured = true;
                    // Working capital balloons, unit cost rises -> margin & covenant suffer, little extra protection.
                    marginDelta -= 0.7; covenantDelta += 0.12; capDelta += 1;
                    if (coachKey === `coach_default` || coachKey === `coach_r3_zero`) coachKey = `coach_r3_overinsure`;
                }

                // Recognise the well-tiered resilience plan.
                if (d.dualSource === `yes` && d.safetyStock >= 2 && d.nearshore >= 1.5 && d.breadth <= 0 && !ds.lineDown) {
                    coachKey = `coach_r3_tiered`;
                }

                summaryKey = (ds.lineDown ? `sum_r3_linedown` :
                             (ds.overInsured ? `sum_r3_overinsure` :
                             (d.dualSource === `yes` && d.safetyStock >= 2 && d.nearshore >= 1.5) ? `sum_r3_good` : `sum_r3_weak`));
            } else if (round === 4) {
                // ---- Defend the renewal and recover. ----
                switch (d.pitch) {
                    case `balanced`:
                        riskDelta -= 12; capDelta += 3; covenantDelta -= 0.08;
                        coachKey = `coach_r4_balanced`;
                        break;
                    case `cost`:
                        // Cost number alone — the client and bank want the full picture.
                        riskDelta += 6; coachKey = `coach_r4_cost`;
                        break;
                    case `loyalty`:
                        riskDelta += 8; coachKey = `coach_r4_loyalty`;
                        break;
                }

                switch (d.model) {
                    case `variable`:
                        marginDelta += 0.6; covenantDelta -= 0.10; capDelta += 4; riskDelta -= 6;
                        if (d.pitch === `balanced`) coachKey = `coach_r4_model`;
                        break;
                    case `fixed`:
                        // Re-fix when the Sol recovers — undoes the operating-leverage gain.
                        covenantDelta += 0.08; capDelta -= 2; riskDelta += 3;
                        if (coachKey === `coach_r4_cost` || coachKey === `coach_r4_loyalty`) { /* keep */ }
                        else coachKey = `coach_r4_refix`;
                        break;
                    case `outsource`:
                        // Chase lowest unit cost everywhere -> risks hollowing the core (TCO blindness).
                        ds.coreLost = true;
                        capDelta -= 8; riskDelta += 10;
                        coachKey = `coach_r4_outsource`;
                        break;
                }

                switch (d.kpi) {
                    case `suite`:
                        riskDelta -= 5; capDelta += 2; break;
                    case `savings`:
                        riskDelta += 3; break;
                    case `margin`:
                        riskDelta += 2; break;
                }

                if (d.conviction >= 60) { capDelta += 2; riskDelta -= 3; }
                else if (d.conviction <= 25) { riskDelta += 3; }

                summaryKey = (d.pitch === `balanced` && d.model === `variable` && d.kpi === `suite`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply deltas (clamped). ----
            ds.savings = Math.max(0, Math.round((ds.savings + savingsDelta) * 10) / 10);
            ds.margin = Math.max(0, Math.min(20, Math.round((ds.margin + marginDelta) * 100) / 100));
            ds.covenant = Math.max(1.5, Math.min(5, Math.round((ds.covenant + covenantDelta) * 100) / 100));
            ds.capability = Math.max(0, Math.min(100, Math.round(ds.capability + capDelta)));
            ds.renewalRisk = Math.max(0, Math.min(100, Math.round(ds.renewalRisk + riskDelta)));

            // ---- STICKY caps: the headline anti-pattern cannot be washed out. ----
            // Losing the core tooling capability caps capability and floors renewal risk.
            if (ds.coreLost) {
                ds.capability = Math.min(ds.capability, 45);
                ds.renewalRisk = Math.max(ds.renewalRisk, 60);
            }
            // A flat haircut keeps the differentiator structurally weaker.
            if (ds.flatHaircut) {
                ds.capability = Math.min(ds.capability, 62);
            }
            // A materialised line-down keeps renewal risk and covenant elevated.
            if (ds.lineDown) {
                ds.renewalRisk = Math.max(ds.renewalRisk, 42);
            }

            ds.savingsHistory.push(ds.savings);
            ds.marginHistory.push(ds.margin);
            ds.covenantHistory.push(ds.covenant);
            ds.capabilityHistory.push(ds.capability);

            // ---- Persist composite where the grading/reporting layer reads it ----
            const _score = this._composite(ds);
            ds.score = _score;
            ds.performance = ds.performance || {};
            ds.performance.overallScore = _score;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                overallScore: _score,
                score: _score,
                savings: ds.savings,
                savingsDelta: Math.round(savingsDelta * 10) / 10,
                margin: ds.margin,
                covenant: ds.covenant,
                capability: ds.capability,
                renewalRisk: ds.renewalRisk,
                coreLost: ds.coreLost,
                lineDown: ds.lineDown,
                lineDownCost: ds.lineDownCost,
                resilienceSpent: ds.resilienceSpent,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _riskLabel(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (v >= 55) return t(`risk_high`);
            if (v >= 32) return t(`risk_mid`);
            return t(`risk_low`);
        }

        _fmtMoney(v) {
            const n = Math.round(Number(v) * 10) / 10;
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            let s = (n % 1 === 0) ? String(n) : n.toFixed(1);
            if (lang === `es`) s = s.replace(`.`, `,`);
            return `S/ ` + s + `M`;
        }

        _fmtPct(v) {
            const n = Math.round(Number(v) * 10) / 10;
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            let s = n.toFixed(1);
            if (lang === `es`) s = s.replace(`.`, `,`);
            return s + `%`;
        }

        _fmtCov(v) {
            const n = Math.round(Number(v) * 100) / 100;
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            let s = n.toFixed(2);
            if (lang === `es`) s = s.replace(`.`, `,`);
            return s + `x`;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`savingsDisplay`, `domainState.savings`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.makebend-card-savings`);
                if (card) {
                    card.classList.toggle(`makebend-savings-hit`, n >= self.TARGET);
                    card.classList.toggle(`makebend-savings-short`, n > 0 && n < self.TARGET);
                }
                return self._fmtMoney(n);
            });

            uiManager.bind(`marginDisplay`, `domainState.margin`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.makebend-card-margin`);
                if (card) card.classList.toggle(`makebend-margin-danger`, n < self.NOACTION_MARGIN);
                return self._fmtPct(n);
            });

            uiManager.bind(`covenantDisplay`, `domainState.covenant`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.makebend-card-covenant`);
                if (card) {
                    card.classList.toggle(`makebend-covenant-breach`, n > self.COVENANT_CAP);
                    card.classList.toggle(`makebend-covenant-safe`, n <= self.COVENANT_CAP);
                }
                return self._fmtCov(n);
            });

            uiManager.bind(`capabilityDisplay`, `domainState.capability`, (v) => `${Math.round(Number(v))}`);

            uiManager.bind(`riskDisplay`, `domainState.renewalRisk`, (v) => {
                const n = Number(v);
                const bar = document.querySelector(`.makebend-risk-bar`);
                if (bar) {
                    bar.classList.toggle(`makebend-risk-low`, n < 32);
                    bar.classList.toggle(`makebend-risk-mid`, n >= 32 && n < 55);
                }
                return self._riskLabel(n);
            });

            // Diagnostic-rigour slider readout (Round 1).
            const dg = document.getElementById(`diagInput`);
            const dgReadout = document.getElementById(`diagReadout`);
            if (dg && dgReadout) {
                dgReadout.textContent = dg.value;
                dg.addEventListener(`input`, function() { dgReadout.textContent = dg.value; });
            }
        }

        getChartConfig() {
            return {
                andicorpChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(`chart_series_savings`) : `Cost savings (S/ M)`,
                                data: [],
                                borderColor: `#2f8f6b`,
                                backgroundColor: `rgba(47,143,107,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#2f8f6b`,
                                yAxisID: `y`
                            },
                            {
                                label: (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(`chart_series_capability`) : `Capability & resilience (0–100)`,
                                data: [],
                                borderColor: `#6a55b0`,
                                backgroundColor: `rgba(106,85,176,0.08)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#6a55b0`,
                                yAxisID: `y`
                            },
                            {
                                label: (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(`chart_series_margin`) : `EBITDA margin (×5, %)`,
                                data: [],
                                borderColor: `#34556e`,
                                backgroundColor: `rgba(52,85,110,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#34556e`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#455463`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#79858f` }, grid: { color: `rgba(31,42,55,0.06)` },
                                title: { display: true, text: `Index / S/ M`, color: `#79858f` }
                            },
                            x: {
                                ticks: { color: `#79858f` }, grid: { color: `rgba(31,42,55,0.04)` },
                                title: { display: true, text: `Round`, color: `#79858f` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.savingsHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // Margin is a small % — scale ×5 to share the 0–100 axis with savings & capability.
            const marginScaled = ds.marginHistory.map((v) => Math.round(v * 5 * 10) / 10);
            return {
                andicorpChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.savingsHistory.map((v) => Math.round(v * 10) / 10) },
                        { data: ds.capabilityHistory },
                        { data: marginScaled }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.0.0 completion formula, now single source of truth and persisted every
            // period so the grading/analytics/LTI layer (domainState.performance.overallScore
            // then top-level score) gets a real number instead of null -> 0.0.
            const savings = Math.round(ds.savings * 10) / 10;
            const margin = Math.round(ds.margin * 10) / 10;
            const covenant = Math.round(ds.covenant * 100) / 100;
            const capability = Math.round(ds.capability);
            const renewalRisk = Math.round(ds.renewalRisk);
            const composite = Math.round(
                Math.min(100, (savings / this.TARGET) * 100) * 0.28 +
                ((margin - this.NOACTION_MARGIN) / (this.START_MARGIN - this.NOACTION_MARGIN)) * 100 * 0.20 +
                Math.max(0, Math.min(100, (this.COVENANT_CAP - covenant + 0.3) / 0.6 * 100)) * 0.18 +
                capability * 0.20 +
                (100 - renewalRisk) * 0.14
            );
            return Math.max(0, Math.min(100, composite));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const savings = Math.round(ds.savings * 10) / 10;
            const margin = Math.round(ds.margin * 10) / 10;
            const covenant = Math.round(ds.covenant * 100) / 100;
            const capability = Math.round(ds.capability);
            const renewalRisk = Math.round(ds.renewalRisk);

            const hitTarget = savings >= this.TARGET;
            const covenantSafe = covenant <= this.COVENANT_CAP;
            const capabilityHeld = capability >= 65 && !ds.coreLost;
            const renewalSafe = renewalRisk < 35;

            // Composite — balanced, but capped hard by the run-defining errors.
            const composite = this._composite(ds);

            // Pattern — which archetype the run resolved to.
            let pattern = `mixed`;
            if (ds.coreLost) pattern = `core_lost`;
            else if (ds.lineDown) pattern = `line_down`;
            else if (ds.overInsured) pattern = `over_insured`;
            else if (ds.flatHaircut) pattern = `flat`;
            else if (ds.identityInertia && !hitTarget) pattern = `inertia`;
            else if (hitTarget && covenantSafe && capabilityHeld && renewalSafe) pattern = `resilient`;

            // Verdict — the headline anti-pattern gates the top verdict via sticky flags.
            let performance = `Capability Broken`, performanceKey = `grade_broken`;
            if (hitTarget && covenantSafe && capabilityHeld && renewalSafe && composite >= 75 && !ds.coreLost && !ds.lineDown) {
                performance = `Resilient & Lean`; performanceKey = `grade_resilient`;
            } else if (ds.coreLost) {
                performance = `Core Outsourced`; performanceKey = `grade_corelost`;
            } else if (ds.lineDown) {
                performance = `Line Down`; performanceKey = `grade_linedown`;
            } else if (ds.overInsured) {
                performance = `Over-Insured`; performanceKey = `grade_overinsured`;
            } else if (ds.identityInertia && !hitTarget) {
                performance = `Identity Inertia`; performanceKey = `grade_inertia`;
            } else if (ds.flatHaircut) {
                performance = `Flat Haircut`; performanceKey = `grade_flat`;
            } else if (composite >= 58) {
                performance = `Partial Recovery`; performanceKey = `grade_partial`;
            }

            const insights = [];
            if (pattern === `resilient`) insights.push(window.mySimulation.t(`insight_resilient`));
            else if (ds.coreLost) insights.push(window.mySimulation.t(`insight_corelost`));
            else if (ds.lineDown) insights.push(window.mySimulation.t(`insight_linedown`));
            else if (ds.overInsured) insights.push(window.mySimulation.t(`insight_overinsure`));
            else if (ds.flatHaircut) insights.push(window.mySimulation.t(`insight_flat`));
            else if (ds.identityInertia) insights.push(window.mySimulation.t(`insight_inertia`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (!hitTarget) insights.push(window.mySimulation.t(`insight_target_miss`));
            if (!covenantSafe) insights.push(window.mySimulation.t(`insight_covenant`));
            if (ds.lineDown) insights.push(window.mySimulation.t(`insight_linedown_cost`));
            if (hitTarget && ds.coreLost) insights.push(window.mySimulation.t(`insight_save_vs_anchor`));

            return {
                savings: savings,
                margin: margin,
                covenant: covenant,
                capability: capability,
                renewalRisk: renewalRisk,
                hitTarget: hitTarget,
                covenantSafe: covenantSafe,
                capabilityHeld: capabilityHeld,
                renewalSafe: renewalSafe,
                coreLost: ds.coreLost,
                lineDown: ds.lineDown,
                lineDownCost: Math.round(ds.lineDownCost * 10) / 10,
                pattern: pattern,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const self = this;
            const t = (window.mySimulation && window.mySimulation.t)
                ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (!summary || typeof summary.composite !== `number`) {
                return `<div class="makebend-cm"><p class="makebend-cm-generic">${t(`cm_generic`)}</p></div>`;
            }
            const tier = summary.performanceKey ? t(summary.performanceKey) : (summary.performance || ``);
            const kpi = (labelKey, valStr) =>
                `<div class="makebend-cm-kpi"><span class="makebend-cm-kpi-val">${valStr}</span>`
                + `<span class="makebend-cm-kpi-lbl">${t(labelKey)}</span></div>`;
            const chip = (ok, labelKey) =>
                `<span class="makebend-cm-chip ${ok ? `is-met` : `is-missed`}">`
                + `${ok ? `✓` : `✗`} ${t(labelKey)}</span>`;
            const insights = (summary.insights || []).map((x) => `<li>${x}</li>`).join(``);
            return ``
                + `<div class="makebend-cm">`
                +   `<div class="makebend-cm-scoreband">`
                +     `<div class="makebend-cm-score">${summary.composite}<span class="makebend-cm-score-max">/100</span></div>`
                +     `<div class="makebend-cm-tier">${tier}</div>`
                +     `<div class="makebend-cm-caption">${t(`cm_caption`)}</div>`
                +   `</div>`
                +   `<div class="makebend-cm-kpis">`
                +     kpi(`cm_kpi_savings`, self._fmtMoney(summary.savings))
                +     kpi(`cm_kpi_margin`, self._fmtPct(summary.margin))
                +     kpi(`cm_kpi_covenant`, self._fmtCov(summary.covenant))
                +     kpi(`cm_kpi_capability`, String(Math.round(summary.capability)))
                +     kpi(`cm_kpi_renewal`, String(Math.round(summary.renewalRisk)))
                +   `</div>`
                +   `<div class="makebend-cm-chips">`
                +     chip(summary.hitTarget, `cm_chip_target`)
                +     chip(summary.covenantSafe, `cm_chip_covenant`)
                +     chip(summary.capabilityHeld, `cm_chip_capability`)
                +     chip(summary.renewalSafe, `cm_chip_renewal`)
                +   `</div>`
                +   (insights ? `<ul class="makebend-cm-insights">${insights}</ul>` : ``)
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.coreLost) return window.mySimulation.t(`hint_corelost`);
            if (ds.lineDown) return window.mySimulation.t(`hint_linedown`);
            if (ds.renewalRisk >= 60) return window.mySimulation.t(`hint_risk`);
            if (ds.overInsured) return window.mySimulation.t(`hint_overinsure`);
            if (ds.covenant > this.COVENANT_CAP && state.currentPeriod >= 2) return window.mySimulation.t(`hint_covenant`);
            if (state.currentPeriod >= 2 && ds.savings < this.TARGET * 0.5) return window.mySimulation.t(`hint_target`);
            if (ds.savings >= this.TARGET && ds.capability >= 65 && ds.renewalRisk < 35) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.savings`, label: `Savings`, i18nKey: `col_savings`, formatter: (v) => self._fmtMoney(Number(v)) },
                { key: `results.margin`, label: `Margin`, i18nKey: `col_margin`, formatter: (v) => self._fmtPct(Number(v)) },
                { key: `results.covenant`, label: `Covenant`, i18nKey: `col_covenant`, formatter: (v) => self._fmtCov(Number(v)) },
                { key: `results.capability`, label: `Capability`, i18nKey: `col_capability`, formatter: (v) => `${Math.round(Number(v))}` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

